INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein gutes Design immer auf Performance ausgelegt?', 2, '[{"text": "Nein", "correct": true, "because": "Wartbarkeit kann wichtiger sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer der Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft mir, meinen Code flexibel zu halten?', 3, '[{"text": "Lose Kopplung", "correct": true, "because": "Reduziert Abhängigkeiten"}, {"text": "Hohe Kohäsion", "correct": false, "because": "Fokus auf Zusammenhalt"}, {"text": "Maximale Wiederverwendung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Planung eines Systems entscheidend?', 5, '[{"text": "Skalierbarkeit", "correct": true, "because": "Wachstum ermöglichen"}, {"text": "Wartbarkeit", "correct": true, "because": "Langfristige Pflege"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Nicht primär"}, {"text": "Minimaler Speicher", "correct": false, "because": "Nur ein Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Designmuster lösen wiederkehrende Probleme. b) Sie garantieren optimale Performance.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Systemplanung, wenn es um Struktur geht?', 4, '[{"text": "Modularität", "correct": false, "because": "Wichtig für Flexibilität"}, {"text": "Abhängigkeiten", "correct": false, "because": "Müssen minimiert werden"}, {"text": "Farbschema der GUI", "correct": true, "because": "Nicht strukturrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein gutes Design immer kompliziert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Einfachheit ist oft besser"}, {"text": "Ja", "correct": false, "because": "Komplexität nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Muster wähle ich für eine flexible Objekterstellung?', 3, '[{"text": "Factory", "correct": true, "because": "Kapselt Instanziierung"}, {"text": "Singleton", "correct": false, "because": "Nur eine Instanz"}, {"text": "Observer", "correct": false, "because": "Für Events"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien machen ein System robust?', 5, '[{"text": "Kapselung", "correct": true, "because": "Schützt Daten"}, {"text": "Redundanz", "correct": true, "because": "Verhindert Ausfälle"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Maximale Zeilen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Design ist nur Planung. b) Es beeinflusst die Wartung. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Design ist mehr als Planung"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist ungenau"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine solide Architektur?', 4, '[{"text": "Klar definierte Schnittstellen", "correct": false, "because": "Fördern Kommunikation"}, {"text": "Dokumentation", "correct": false, "because": "Hilft bei Wartung"}, {"text": "Schicke Icons", "correct": true, "because": "Rein kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein gutes Design immer teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Kostet Zeit, nicht immer Geld"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördern die Wiederverwendbarkeit?', 4, '[{"text": "Modularität", "correct": true, "because": "Unabhängige Komponenten"}, {"text": "Generische Schnittstellen", "correct": true, "because": "Breitere Nutzung"}, {"text": "Spezifische Hardware", "correct": false, "because": "Einschränkend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Design nur für große Projekte wichtig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Größe egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Systemgestaltung?', 3, '[{"text": "Klarheit der Struktur", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Implementierung", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Minimaler Code", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein gutes Design reduziert Fehler. b) Es verzögert die Entwicklung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwangsläufig wahr"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein durchdachtes Design?', 5, '[{"text": "Einfachere Wartung", "correct": true, "because": "Struktur klar"}, {"text": "Bessere Skalierung", "correct": true, "because": "Anpassungsfähig"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Hardware", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Planung unwichtig?', 3, '[{"text": "Komponententrennung", "correct": false, "because": "Fördert Flexibilität"}, {"text": "Konsistenz", "correct": false, "because": "Vermeidet Chaos"}, {"text": "Programmiersprache", "correct": true, "because": "Design ist abstrakt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Spart ein gutes Design immer Zeit?', 3, '[{"text": "Nein", "correct": true, "because": "Investition kann länger dauern"}, {"text": "Ja", "correct": false, "because": "Kurzfristig mehr Aufwand"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Design nur für Entwickler relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Admins und Architekten"}, {"text": "Ja", "correct": false, "because": "Breitere Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem soliden Design?', 4, '[{"text": "Langfristige Stabilität", "correct": true, "because": "Reduziert Probleme"}, {"text": "Sofortige Fertigstellung", "correct": false, "because": "Qualität braucht Zeit"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht immer günstig"}]');
